#include <linux/fscrypt.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>
int main(int argc, char **argv) {
    if (argc != 2) return 2;
    int fd = open(argv[1], O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC);
    if (fd < 0) { perror("open private encrypted directory"); return 1; }
    struct fscrypt_policy_v2 policy = {0};
    policy.version = FSCRYPT_POLICY_V2;
    policy.contents_encryption_mode = FSCRYPT_MODE_AES_256_XTS;
    policy.filenames_encryption_mode = FSCRYPT_MODE_AES_256_CTS;
    for (unsigned i = 0; i < sizeof(policy.master_key_identifier); ++i) policy.master_key_identifier[i] = (unsigned char)(0xa0 + i);
    /* Public, deliberately unavailable key identifier. No key material exists.
       CAP_FOWNER is used only by this private-fixture setup helper. */
    if (ioctl(fd, FS_IOC_SET_ENCRYPTION_POLICY, &policy) != 0) { perror("set private v2 policy"); close(fd); return 1; }
    struct fscrypt_get_key_status_arg status = {0};
    status.key_spec.type = FSCRYPT_KEY_SPEC_TYPE_IDENTIFIER;
    memcpy(status.key_spec.u.identifier, policy.master_key_identifier, sizeof(policy.master_key_identifier));
    if (ioctl(fd, FS_IOC_GET_ENCRYPTION_KEY_STATUS, &status) != 0) { perror("private key status"); close(fd); return 1; }
    if (status.status != FSCRYPT_KEY_STATUS_ABSENT) { close(fd); return 1; }
    close(fd);
    puts("private fscrypt v2 directory policy set; key status ABSENT; no keys added");
    return 0;
}
